Get-ChildItem -Path 'c:\Codeverse\public', 'c:\Codeverse\' -Include *.html,*.js,*.css -Recurse -File | ForEach-Object { $content = Get-Content $_.FullName -Raw; $newContent = $content -replace 'Metaverse Club', 'Metaversity Club' -replace 'METAVERSE CLUB', 'METAVERSITY CLUB' -replace 'Metaverse_Admin', 'Metaversity_Admin'; if ($content -cne $newContent) { Set-Content -Path $_.FullName -Value $newContent -NoNewline; Write-Host "Updated $($_.FullName)" } }
